export{ModalEmpleadoCtrl};function ModalEmpleadoCtrl($scope,mS,empleadoSvc,$uibModalInstance,tS,params){function onInit(){mS.getData("post","/TipoIdentificacion/ReadTipoIdentificacion",{tipoValidacion:"V"}).then(response=>{$scope.tipoIdentificaciones=response.data,$scope.data.idTipoIdentificacion=$scope.tipoIdentificaciones[0].idTipoIdentificacion,$scope.data.identificacion=$scope.tipoIdentificaciones[0].identificacion,console.log($scope.tipoIdentificaciones)}),params&&params.idEmpleado>0&&($scope.tipoRegistro=2,$scope.data=Object.assign({},params))}$scope.tipoRegistro=1,$scope.data={},onInit(),$scope.onChangeTipoIdentificacion=function(){$scope.data.identificacion=$scope.tipoIdentificaciones.find(item=>item.idTipoIdentificacion===$scope.data.idTipoIdentificacion).identificacion},$scope.saveAndUpdate=function(){try{const titulo=1===$scope.tipoRegistro?"Guardar":"Actualizar";if(!($scope.data.idTipoIdentificacion>0))return void tS.toastr("warning","Seleccione el Tipo Identificación",titulo);let{codigo:codigoIdentificacion}=$scope.tipoIdentificaciones.find(item=>item.idTipoIdentificacion===$scope.data.idTipoIdentificacion);if(!$scope.data.nroIdentificacion)return void tS.toastr("warning","Ingrese Nro. de Identificación",titulo);if("04"===codigoIdentificacion&&13!==$scope.data.nroIdentificacion.length)return void tS.toastr("warning","Numero de ruc debe tener 13 digítos",titulo);if("04"===codigoIdentificacion&&"001"!==$scope.data.nroIdentificacion.slice($scope.data.nroIdentificacion.length-3))return void tS.toastr("warning","Número de RUC tiene que contener (001) en últimos dígitos");if("05"===codigoIdentificacion&&10!==$scope.data.nroIdentificacion.length)return void tS.toastr("warning","Numero de cedula debe tener 10 digítos",titulo);if(1===$scope.tipoRegistro){if(!$scope.data.nombre)return void tS.toastr("warning","Ingrese el Nombre",titulo);if(!$scope.data.apellido)return void tS.toastr("warning","Ingrese el Apellido",titulo);$scope.data.nombreCompleto=$scope.data.nombre+" "+$scope.data.apellido}if(2===$scope.tipoRegistro&&!$scope.data.nombreCompleto)return void tS.toastr("warning","Ingrese el Nombre Completo",titulo);const data={idEmpleado:$scope.data.idEmpleado,idTipoIdentificacion:$scope.data.idTipoIdentificacion,nroIdentificacion:$scope.data.nroIdentificacion,nombreCompleto:$scope.data.nombreCompleto,estado:$scope.data.estado};showLoader(),data.idEmpleado>0?empleadoSvc.update($scope.data.idEmpleado,data).then($scope.successResponse).catch(error=>{hideLoader(),console.log(error)}):empleadoSvc.save(data).then($scope.successResponse).catch(error=>{hideLoader(),console.log(error)})}catch(error){hideLoader(),toastr.error(error)}},$scope.successResponse=function(response){hideLoader(),"0"!=response.code?"1"==response.code&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response)):tS.toastr("warning",response.message,response.titleSms)},$scope.closeModal=function(){$uibModalInstance.close()}}ModalEmpleadoCtrl.$inject=["$scope","mainService","empleadoService","$uibModalInstance","toastService","params"];